/**
 * 4 Historical Themes - High Aesthetic Quality
 * 四种历史风格主题 - 高水平美学
 * 
 * 设计原则：
 * 1. 控制面板始终使用深色半透明背景，确保文字清晰可读
 * 2. 3D棋盘区域使用主题特定背景
 * 3. 棋子颜色符合历史风格且对比度足够
 * 4. 所有主题都保证良好的视觉层次
 */

import { Theme } from '../../../shared/types';

// Theme 1: 秦汉古韵 - Ancient Bronze
// 特点：古朴典雅，暖色调，轻盈明亮
export const qinhanTheme: Theme = {
  id: 'qinhan',
  name: '秦汉古韵',
  nameEn: 'Ancient Qin & Han',
  description: '古朴典雅，暖铜色调，彰显秦汉帝国的雄浑气魄',
  colors: {
    primary: '#C4956A',           // 浅青铜色
    secondary: '#E8C547',         // 明金色
    accent: '#D4A574',            // 浅秘鲁色
    background: '#3D3020',        // 浅暖棕（3D区域）- 更轻盈
    board: '#A67C52',             // 浅木色棋盘 - 不厚重
    pieceRed: '#D9534F',          // 珊瑚红 - 明亮
    pieceBlack: '#5D4E37',        // 暖褐色 - 柔和不沉重
    grid: '#E8C547',              // 金色网格
    highlight: '#FFD700',         // 亮金高亮
    selection: '#FF8C42',         // 橙红选中
  },
  materials: {
    board: 'bronze-textured-wood',
    piece: 'bronze-with-patina',
    highlight: 'glowing-gold',
  },
  lighting: {
    ambient: 0.55,
    directional: 1.1,
    point: 0.75,
  },
};

// Theme 2: 唐宋风华 - Golden Glory
// 特点：华丽精致，金红配色，明亮大气
export const tangsongTheme: Theme = {
  id: 'tangsong',
  name: '唐宋风华',
  nameEn: 'Tang & Song Glory',
  description: '华丽精致，金红辉煌，展现唐宋盛世的繁华气象',
  colors: {
    primary: '#E8C547',           // 明金色
    secondary: '#E85D75',         // 玫瑰红 - 更柔和
    accent: '#5D8AA8',            // 浅钢蓝
    background: '#2A2A3E',        // 浅蓝紫（3D区域）- 更轻盈
    board: '#3D3D5C',             // 中紫棋盘 - 不沉重
    pieceRed: '#E85D75',          // 玫瑰红 - 明亮柔和
    pieceBlack: '#4A5568',        // 灰蓝色 - 现代感，不沉重
    grid: '#E8C547',              // 金色网格
    highlight: '#FFD700',         // 亮金高亮
    selection: '#FF7F50',         // 珊瑚选中
  },
  materials: {
    board: 'polished-jade-with-gold-inlay',
    piece: 'porcelain-with-gold-trim',
    highlight: 'ethereal-gold-glow',
  },
  lighting: {
    ambient: 0.55,
    directional: 1.2,
    point: 0.85,
  },
};

// Theme 3: 明清雅致 - Elegant Rosewood
// 特点：简洁优雅，红木质感，温暖舒适
export const mingqingTheme: Theme = {
  id: 'mingqing',
  name: '明清雅致',
  nameEn: 'Ming & Qing Elegance',
  description: '简洁优雅，红木质感，体现明清文人的雅致品味',
  colors: {
    primary: '#A0522D',           // 赭色 - 更柔和
    secondary: '#FAF0E6',         // 亚麻色
    accent: '#708090',            // 石板灰 - 更浅
    background: '#2D2420',        // 浅暖灰（3D区域）- 不沉重
    board: '#5D4E44',             // 浅红木色棋盘 - 更轻盈
    pieceRed: '#CD5C5C',          // 印度红 - 柔和
    pieceBlack: '#4A4A4A',        // 中灰 - 不沉重
    grid: '#C4956A',              // 浅棕色网格
    highlight: '#E8A87C',         // 浅橙高亮
    selection: '#F4A460',         // 沙棕选中
  },
  materials: {
    board: 'rosewood-with-grain',
    piece: 'carved-rosewood',
    highlight: 'warm-amber-glow',
  },
  lighting: {
    ambient: 0.6,
    directional: 1.05,
    point: 0.7,
  },
};

// Theme 4: 现代简约 - Modern Minimalist
// 特点：极简设计，深色棋盘配明亮棋子，现代优雅
export const modernTheme: Theme = {
  id: 'modern',
  name: '现代简约',
  nameEn: 'Modern Minimalist',
  description: '极简设计，深色棋盘配明亮棋子，诠释现代美学的纯粹之美',
  colors: {
    primary: '#2C3E50',           // 深蓝灰
    secondary: '#E74C3C',         // 现代红
    accent: '#3498DB',            // 现代蓝
    background: '#2C3E50',        // 深蓝灰（3D区域）
    board: '#34495E',             // 中灰蓝棋盘 - 深色确保网格清晰
    pieceRed: '#FF6B6B',          // 珊瑚红 - 明亮现代
    pieceBlack: '#4ECDC4',        // 青绿色 - 现代感强，与红方形成对比
    grid: '#5D6D7E',              // 浅灰蓝网格 - 清晰可见
    highlight: '#3498DB',         // 现代蓝高亮
    selection: '#F39C12',         // 现代橙选中
  },
  materials: {
    board: 'frosted-glass',
    piece: 'translucent-crystal',
    highlight: 'neon-blue-glow',
  },
  lighting: {
    ambient: 0.6,
    directional: 1.1,
    point: 0.7,
  },
};

export const themes = {
  qinhan: qinhanTheme,
  tangsong: tangsongTheme,
  mingqing: mingqingTheme,
  modern: modernTheme,
};

export const defaultTheme = mingqingTheme;

// 导出主题特定的UI配色（用于控制面板）
export const uiColors = {
  // 控制面板背景 - 所有主题使用深色半透明，确保文字清晰
  panelBg: 'rgba(30, 30, 40, 0.85)',
  panelBorder: 'rgba(255, 255, 255, 0.1)',

  // 文字颜色
  textPrimary: '#FFFFFF',
  textSecondary: 'rgba(255, 255, 255, 0.7)',
  textMuted: 'rgba(255, 255, 255, 0.5)',

  // 按钮样式
  buttonBg: 'rgba(255, 255, 255, 0.1)',
  buttonBgHover: 'rgba(255, 255, 255, 0.15)',
  buttonBorder: 'rgba(255, 255, 255, 0.2)',

  // 选中状态
  activeBg: 'rgba(212, 175, 55, 0.25)',
  activeBorder: '#D4AF37',
  activeText: '#FFD700',
};

input.content:
/**
 * 3D中国象棋 v2 - 高水平美学主题系统
 * 使用 threejs-textures + game-ui-design + frontend 技能优化
 * 
 * 升级内容：
 * 1. PBR材质系统 (threejs-textures)
 * 2. 游戏UI设计模式 (game-ui-design)
 * 3. 专业配色系统 (frontend)
 * 4. 动画规范 (frontend)
 */

import * as THREE from 'three';

// ============================================
// 材质生成器 - 基于 threejs-textures 技能
// ============================================

export interface MaterialConfig {
  color: string;
  metalness: number;
  roughness: number;
  normalScale?: number;
  envMapIntensity?: number;
  clearcoat?: number;
  transmission?: number;
}

export class MaterialGenerator {
  static createBronzeMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0x8B7355,
      metalness: 0.85,
      roughness: 0.35,
      envMapIntensity: 1.0,
    });
  }

  static createJadeMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0x2E8B57,
      metalness: 0.1,
      roughness: 0.15,
      transmission: 0.3,
      thickness: 0.5,
      clearcoat: 0.8,
      clearcoatRoughness: 0.1,
    });
  }

  static createRosewoodMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0x8B4513,
      metalness: 0.05,
      roughness: 0.75,
    });
  }

  static createGlassMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      metalness: 0,
      roughness: 0.05,
      transmission: 0.95,
      thickness: 0.3,
      ior: 1.5,
      clearcoat: 1.0,
    });
  }

  static createGoldMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0xFFD700,
      metalness: 1.0,
      roughness: 0.15,
      envMapIntensity: 1.2,
    });
  }

  static createPorcelainMaterial(color: number): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: color,
      metalness: 0.1,
      roughness: 0.2,
      clearcoat: 0.9,
      clearcoatRoughness: 0.05,
    });
  }
}

// ============================================
// 主题定义 - 基于 game-ui-design + frontend 技能
// ============================================

export interface Theme {
  id: string;
  name: string;
  nameEn: string;
  description: string;
  era: string;

  // 颜色系统 - 70-20-10 规则
  colors: {
    primary: string;      // 70% - 主色
    secondary: string;    // 20% - 辅助色
    accent: string;       // 10% - 点缀色
    background: string;   // 背景色
    surface: string;      // 表面色
    board: string;        // 棋盘色
    pieceRed: string;     // 红方棋子
    pieceBlack: string;   // 黑方棋子
    grid: string;         // 网格线
    highlight: string;    // 高亮
    selection: string;    // 选中
    text: string;         // 文字
    textMuted: string;    // 次要文字
  };

  // 材质配置
  materials: {
    board: THREE.Material;
    pieceRed: THREE.Material;
    pieceBlack: THREE.Material;
    highlight: THREE.Material;
    grid: THREE.Material;
  };

  // 光照配置
  lighting: {
    ambient: number;
    directional: number;
    point: number;
    color: number;
  };

  // UI配置 - 基于 game-ui-design
  ui: {
    panelBg: string;
    panelBorder: string;
    buttonBg: string;
    buttonHover: string;
    buttonActive: string;
    fontFamily: string;
    borderRadius: string;
    shadow: string;
  };

  // 动画配置 - 基于 frontend
  animation: {
    pieceMove: number;    // 棋子移动时长
    capture: number;      // 吃子特效时长
    uiTransition: number; // UI过渡时长
    hover: number;        // 悬停反馈时长
    stagger: number;      // 交错动画延迟
  };
}

// ============================================
// 主题 1: 秦汉古韵 - 青铜帝国
// ============================================

export const qinhanTheme: Theme = {
  id: 'qinhan',
  name: '秦汉古韵',
  nameEn: 'Qin & Han Bronze',
  description: '古朴典雅，青铜质感，彰显秦汉帝国的雄浑气魄',
  era: '221 BC - 220 AD',

  colors: {
    primary: '#8B7355',      // 青铜色 70%
    secondary: '#D4AF37',    // 金色 20%
    accent: '#CD853F',       // 秘鲁色 10%
    background: '#1A1510',   // 深棕黑
    surface: '#2A2018',      // 表面色
    board: '#A67C52',        // 浅青铜棋盘
    pieceRed: '#B87333',     // 铜红
    pieceBlack: '#4A3728',   // 深铜色
    grid: '#D4AF37',         // 金色网格
    highlight: '#FFD700',    // 亮金高亮
    selection: '#FF8C42',    // 橙红选中
    text: '#F5DEB3',         // 小麦色文字
    textMuted: '#C4956A',    // 柔和文字
  },

  materials: {
    board: MaterialGenerator.createBronzeMaterial(),
    pieceRed: MaterialGenerator.createBronzeMaterial(),
    pieceBlack: new THREE.MeshStandardMaterial({
      color: 0x4A3728,
      metalness: 0.8,
      roughness: 0.4,
    }),
    highlight: MaterialGenerator.createGoldMaterial(),
    grid: MaterialGenerator.createGoldMaterial(),
  },

  lighting: {
    ambient: 0.4,
    directional: 1.0,
    point: 0.6,
    color: 0xFFE4B5,
  },

  // UI设计 - 基于 game-ui-design 原则
  ui: {
    panelBg: 'rgba(26, 21, 16, 0.92)',
    panelBorder: 'rgba(212, 175, 55, 0.3)',
    buttonBg: 'rgba(139, 115, 85, 0.3)',
    buttonHover: 'rgba(139, 115, 85, 0.5)',
    buttonActive: 'rgba(212, 175, 55, 0.4)',
    fontFamily: '"Playfair Display", "Noto Serif SC", serif',
    borderRadius: '4px',
    shadow: '0 4px 20px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255,255,255,0.1)',
  },

  // 动画规范 - 基于 frontend
  animation: {
    pieceMove: 300,      // 300ms ease-out
    capture: 500,        // 500ms 粒子消散
    uiTransition: 250,   // 250ms 平滑过渡
    hover: 150,          // 150ms 快速反馈
    stagger: 80,         // 80ms 交错
  },
};

// ============================================
// 主题 2: 唐宋风华 - 金玉辉煌
// ============================================

export const tangsongTheme: Theme = {
  id: 'tangsong',
  name: '唐宋风华',
  nameEn: 'Tang & Song Glory',
  description: '华丽精致，金镶玉质，展现唐宋盛世的繁华气象',
  era: '618 - 1279 AD',

  colors: {
    primary: '#D4AF37',      // 金色 70%
    secondary: '#2E8B57',    // 玉绿 20%
    accent: '#E85D75',       // 玫瑰红 10%
    background: '#0F1419',   // 深蓝黑
    surface: '#1A2332',      // 表面色
    board: '#2A3D4D',        // 深蓝棋盘
    pieceRed: '#E85D75',     // 玫瑰红棋子
    pieceBlack: '#4A90A4',   // 青蓝棋子
    grid: '#D4AF37',         // 金色网格
    highlight: '#FFD700',    // 亮金高亮
    selection: '#FF7F50',    // 珊瑚选中
    text: '#F5F5DC',         // 米色文字
    textMuted: '#B8B8B8',    // 柔和文字
  },

  materials: {
    board: MaterialGenerator.createJadeMaterial(),
    pieceRed: MaterialGenerator.createPorcelainMaterial(0xE85D75),
    pieceBlack: MaterialGenerator.createPorcelainMaterial(0x4A90A4),
    highlight: MaterialGenerator.createGoldMaterial(),
    grid: MaterialGenerator.createGoldMaterial(),
  },

  lighting: {
    ambient: 0.45,
    directional: 1.1,
    point: 0.7,
    color: 0xFFF8DC,
  },

  ui: {
    panelBg: 'rgba(15, 20, 25, 0.92)',
    panelBorder: 'rgba(212, 175, 55, 0.4)',
    buttonBg: 'rgba(46, 139, 87, 0.3)',
    buttonHover: 'rgba(46, 139, 87, 0.5)',
    buttonActive: 'rgba(212, 175, 55, 0.4)',
    fontFamily: '"Noto Serif SC", "Playfair Display", serif',
    borderRadius: '6px',
    shadow: '0 4px 24px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255,255,255,0.15)',
  },

  animation: {
    pieceMove: 280,
    capture: 600,
    uiTransition: 300,
    hover: 150,
    stagger: 100,
  },
};

// ============================================
// 主题 3: 明清雅致 - 红木文韵
// ============================================

export const mingqingTheme: Theme = {
  id: 'mingqing',
  name: '明清雅致',
  nameEn: 'Ming & Qing Elegance',
  description: '简洁优雅，红木质感，体现明清文人的雅致品味',
  era: '1368 - 1912 AD',

  colors: {
    primary: '#8B4513',      // 红木色 70%
    secondary: '#FAF0E6',    // 亚麻色 20%
    accent: '#CD5C5C',       // 印度红 10%
    background: '#1E1814',   // 深棕
    surface: '#2D2420',      // 表面色
    board: '#5D4E44',        // 浅红木棋盘
    pieceRed: '#CD5C5C',     // 柔和红
    pieceBlack: '#4A4A4A',   // 雅致灰
    grid: '#C4956A',         // 浅棕网格
    highlight: '#E8A87C',    // 浅橙高亮
    selection: '#F4A460',    // 沙棕选中
    text: '#FAF0E6',         // 亚麻色文字
    textMuted: '#C4B9A8',    // 柔和文字
  },

  materials: {
    board: MaterialGenerator.createRosewoodMaterial(),
    pieceRed: new THREE.MeshStandardMaterial({
      color: 0xCD5C5C,
      metalness: 0.1,
      roughness: 0.4,
    }),
    pieceBlack: new THREE.MeshStandardMaterial({
      color: 0x4A4A4A,
      metalness: 0.1,
      roughness: 0.5,
    }),
    highlight: new THREE.MeshStandardMaterial({
      color: 0xE8A87C,
      emissive: 0xE8A87C,
      emissiveIntensity: 0.3,
    }),
    grid: new THREE.MeshStandardMaterial({
      color: 0xC4956A,
    }),
  },

  lighting: {
    ambient: 0.5,
    directional: 1.0,
    point: 0.6,
    color: 0xFFF5E6,
  },

  ui: {
    panelBg: 'rgba(30, 24, 20, 0.92)',
    panelBorder: 'rgba(139, 69, 19, 0.3)',
    buttonBg: 'rgba(139, 69, 19, 0.3)',
    buttonHover: 'rgba(139, 69, 19, 0.5)',
    buttonActive: 'rgba(205, 92, 92, 0.4)',
    fontFamily: '"Noto Serif SC", "Source Han Serif CN", serif',
    borderRadius: '2px',
    shadow: '0 4px 16px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255,255,255,0.05)',
  },

  animation: {
    pieceMove: 350,
    capture: 450,
    uiTransition: 280,
    hover: 180,
    stagger: 120,
  },
};

// ============================================
// 主题 4: 现代简约 - 水晶玻璃
// ============================================

export const modernTheme: Theme = {
  id: 'modern',
  name: '现代简约',
  nameEn: 'Modern Minimalist',
  description: '极简设计，水晶玻璃，诠释现代美学的纯粹之美',
  era: 'Modern',

  colors: {
    primary: '#2C3E50',      // 深蓝灰 70%
    secondary: '#ECF0F1',    // 浅灰 20%
    accent: '#3498DB',       // 现代蓝 10%
    background: '#1A1A2E',   // 深紫黑
    surface: '#16213E',      // 表面色
    board: 'rgba(255,255,255,0.05)', // 透明棋盘
    pieceRed: '#FF6B6B',     // 珊瑚红
    pieceBlack: '#4ECDC4',   // 青绿
    grid: 'rgba(255,255,255,0.2)', // 半透明网格
    highlight: '#3498DB',    // 现代蓝高亮
    selection: '#F39C12',    // 现代橙选中
    text: '#FFFFFF',         // 纯白文字
    textMuted: 'rgba(255,255,255,0.6)', // 半透明文字
  },

  materials: {
    board: MaterialGenerator.createGlassMaterial(),
    pieceRed: new THREE.MeshPhysicalMaterial({
      color: 0xFF6B6B,
      transmission: 0.6,
      thickness: 0.4,
      roughness: 0.1,
      clearcoat: 1.0,
    }),
    pieceBlack: new THREE.MeshPhysicalMaterial({
      color: 0x4ECDC4,
      transmission: 0.6,
      thickness: 0.4,
      roughness: 0.1,
      clearcoat: 1.0,
    }),
    highlight: new THREE.MeshBasicMaterial({
      color: 0x3498DB,
      transparent: true,
      opacity: 0.8,
    }),
    grid: new THREE.MeshBasicMaterial({
      color: 0xFFFFFF,
      transparent: true,
      opacity: 0.3,
    }),
  },

  lighting: {
    ambient: 0.6,
    directional: 1.2,
    point: 0.8,
    color: 0xFFFFFF,
  },

  ui: {
    panelBg: 'rgba(26, 26, 46, 0.85)',
    panelBorder: 'rgba(255, 255, 255, 0.1)',
    buttonBg: 'rgba(255, 255, 255, 0.1)',
    buttonHover: 'rgba(255, 255, 255, 0.2)',
    buttonActive: 'rgba(52, 152, 219, 0.4)',
    fontFamily: '"Inter", "Plus Jakarta Sans", sans-serif',
    borderRadius: '12px',
    shadow: '0 8px 32px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255,255,255,0.1)',
  },

  animation: {
    pieceMove: 250,
    capture: 400,
    uiTransition: 200,
    hover: 120,
    stagger: 60,
  },
};

// ============================================
// 导出所有主题
// ============================================

export const themes: Record<string, Theme> = {
  qinhan: qinhanTheme,
  tangsong: tangsongTheme,
  mingqing: mingqingTheme,
  modern: modernTheme,
};

export const defaultTheme = mingqingTheme;

// 主题切换动画配置
export const themeTransition = {
  duration: 500,
  ease: [0.4, 0, 0.2, 1], // ease-out
};

// 棋子移动动画配置 - 基于 game-ui-design
export const pieceMoveAnimation = {
  duration: 300,
  ease: 'easeOut',
  keyframes: {
    start: { scale: 1, y: 0 },
    lift: { scale: 1.1, y: 0.5 },
    move: { scale: 1.1, y: 0.5 },
    place: { scale: 1, y: 0 },
  },
};

// 吃子特效配置
export const captureEffect = {
  particleCount: 20,
  spread: 2,
      duration: 500,
  colors: ['#FFD700', '#FF6B6B', '#FFFFFF'],
};

// UI动画配置 - 基于 frontend
export const uiAnimation = {
  fast: 150,      // 悬停、点击
  normal: 300,    // 过渡、展开
  slow: 500,      // 页面切换
  stagger: 80,    // 交错延迟
};

