  roughness: number;
  normalScale?: number;
  envMapIntensity?: number;
  clearcoat?: number;
  transmission?: number;
}

export class MaterialGenerator {
  static createBronzeMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0x8B7355,
      metalness: 0.85,
      roughness: 0.35,
      envMapIntensity: 1.0,
    });
  }

  static createJadeMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0x2E8B57,
      metalness: 0.1,
      roughness: 0.15,
      transmission: 0.3,
      thickness: 0.5,
      clearcoat: 0.8,
      clearcoatRoughness: 0.1,
    });
  }

  static createRosewoodMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0x8B4513,
      metalness: 0.05,
      roughness: 0.75,
    });
