  static createGlassMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      metalness: 0,
      roughness: 0.05,
      transmission: 0.95,
      thickness: 0.3,
      ior: 1.5,
      clearcoat: 1.0,
