    return new THREE.MeshPhysicalMaterial({
      color: 0x2E8B57,
      metalness: 0.1,
      roughness: 0.15,
      transmission: 0.3,
      thickness: 0.5,
      clearcoat: 0.8,
      clearcoatRoughness: 0.1,
    });
  }

  static createRosewoodMaterial(textureLoader: THREE.TextureLoader): THREE.MeshStandardMaterial {
    const colorMap = textureLoader.load('/textures/rosewood_texture.png');
    return new THREE.MeshStandardMaterial({
      color: 0x8B4513,
      metalness: 0.05,
      roughness: 0.75,
      map: colorMap,
    });
  }

  static createGlassMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      metalness: 0,
      roughness: 0.05,
      transmission: 0.95,
      thickness: 0.3,
      ior: 1.5,
      clearcoat: 1.0,
