  static createGoldMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0xFFD700,
      metalness: 1.0,
      roughness: 0.15,
      envMapIntensity: 1.2,
    });
  }
}

