 */

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Theme, themes, defaultTheme } from '../themes';

// ============================================
// 类型定义
// ============================================

interface GameUIProps {
  themeId?: string;
  onThemeChange?: (themeId: string) => void;
  currentPlayer?: 'red' | 'black';
  moveHistory?: string[];
  capturedPieces?: { red: string[]; black: string[] };
  timer?: { red: number; black: number };
  onUndo?: () => void;
  onReset?: () => void;
  onSettings?: () => void;
}

interface PanelProps {
  theme: Theme;
  children: React.ReactNode;
  title?: string;
  className?: string;
}

// ============================================
// 基础组件: 面板
// ============================================

function Panel({ theme, children, title, className = '' }: PanelProps) {
  return (
    <motion.div
      className={`rounded-lg overflow-hidden ${className}`}
      style={{
        background: theme.ui.panelBg,
        border: `1px solid ${theme.ui.panelBorder}`,
        borderRadius: theme.ui.borderRadius,
        boxShadow: theme.ui.shadow,
      }}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: theme.animation.uiTransition / 1000 }}
    >
      {title && (
        <div 
          className="px-4 py-3 border-b"
          style={{ borderColor: theme.ui.panelBorder }}
        >
          <h3 
            className="text-lg font-semibold"
            style={{ 
              color: theme.colors.text,
              fontFamily: theme.ui.fontFamily,
            }}
          >
            {title}
          </h3>
        </div>
      )}
      <div className="p-4">
        {children}
      </div>
    </motion.div>
  );
}

// ============================================
// 基础组件: 按钮
// ============================================

interface ButtonProps {
  theme: Theme;
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  icon?: React.ReactNode;
}

function Button({ 
  theme, 
  children, 
  onClick, 
  variant = 'secondary',
  size = 'md',
  disabled = false,
  icon,
}: ButtonProps) {
  const sizeClasses = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2',
    lg: 'px-6 py-3 text-lg',
  };

  const getBackground = () => {
    if (disabled) return 'rgba(128,128,128,0.2)';
    switch (variant) {
      case 'primary': return theme.colors.accent;
      case 'secondary': return theme.ui.buttonBg;
      case 'ghost': return 'transparent';
      default: return theme.ui.buttonBg;
    }
  };

  return (
    <motion.button
      onClick={onClick}
      disabled={disabled}
      className={`flex items-center justify-center gap-2 font-medium transition-all ${sizeClasses[size]}`}
      style={{
        background: getBackground(),
        color: theme.colors.text,
        borderRadius: theme.ui.borderRadius,
        fontFamily: theme.ui.fontFamily,
        border: variant === 'ghost' ? `1px solid ${theme.ui.panelBorder}` : 'none',
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? 'not-allowed' : 'pointer',
      }}
      whileHover={!disabled ? { 
        background: variant === 'primary' ? theme.colors.accent : theme.ui.buttonHover,
        scale: 1.02,
      } : {}}
      whileTap={!disabled ? { scale: 0.98 } : {}}
      transition={{ duration: theme.animation.hover / 1000 }}
    >
      {icon && <span>{icon}</span>}
      {children}
    </motion.button>
  );
}

// ============================================
// 组件: 玩家信息面板
// ============================================

interface PlayerInfoProps {
  theme: Theme;
  isRed: boolean;
  isActive: boolean;
  time: number;
  capturedCount: number;
}

function PlayerInfo({ theme, isRed, isActive, time, capturedCount }: PlayerInfoProps) {
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <motion.div
      className="flex items-center gap-4 p-4 rounded-lg"
      style={{
        background: isActive ? `${theme.colors.accent}20` : theme.colors.surface,
        border: `2px solid ${isActive ? theme.colors.accent : theme.ui.panelBorder}`,
        borderRadius: theme.ui.borderRadius,
      }}
      animate={isActive ? {
        boxShadow: [`0 0 0px ${theme.colors.accent}00`, `0 0 20px ${theme.colors.accent}40`, `0 0 0px ${theme.colors.accent}00`],
      } : {}}
      transition={{ duration: 2, repeat: Infinity }}
    >
      {/* 玩家头像/标识 */}
      <div
        className="w-12 h-12 rounded-full flex items-center justify-center text-2xl font-bold"
        style={{
          background: isRed ? theme.colors.pieceRed : theme.colors.pieceBlack,
          color: '#FFF',
          fontFamily: theme.ui.fontFamily,
        }}
      >
        {isRed ? '红' : '黑'}
      </div>

      {/* 玩家信息 */}
      <div className="flex-1">
        <div 
          className="font-semibold text-lg"
          style={{ 
            color: theme.colors.text,
            fontFamily: theme.ui.fontFamily,
          }}
        >
          {isRed ? '红方' : '黑方'}
          {isActive && (
            <span 
              className="ml-2 text-sm px-2 py-0.5 rounded"
              style={{ 
                background: theme.colors.accent,
                color: '#FFF',
              }}
            >
              当前回合
            </span>
          )}
        </div>
        <div 
          className="text-sm"
          style={{ color: theme.colors.textMuted }}
        >
          用时: {formatTime(time)} | 吃子: {capturedCount}
        </div>
      </div>
    </motion.div>
  );
}

