  };

  return (
    <Panel theme={theme} title="吃子记录">
      <div className="space-y-4">
        {/* 红方吃子 */}
        <div>
          <div 
            className="text-sm font-medium mb-2"
            style={{ color: theme.colors.pieceRed }}
          >
            红方吃掉
          </div>
          <div className="flex flex-wrap gap-1">
            {capturedPieces.red.length === 0 ? (
              <span style={{ color: theme.colors.textMuted }}>无</span>
            ) : (
              capturedPieces.red.map((piece, i) => (
                <motion.span
                  key={i}
                  className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold"
                  style={{
                    background: theme.colors.pieceBlack,
                    color: '#C0C0C0',
                    border: '1px solid #666',
                  }}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ delay: i * 0.05 }}
                >
                  {pieceIcons[piece] || piece}
                </motion.span>
              ))
            )}
          </div>
        </div>

        {/* 黑方吃子 */}
        <div>
          <div 
            className="text-sm font-medium mb-2"
            style={{ color: theme.colors.pieceBlack }}
          >
            黑方吃掉
          </div>
          <div className="flex flex-wrap gap-1">
            {capturedPieces.black.length === 0 ? (
              <span style={{ color: theme.colors.textMuted }}>无</span>
            ) : (
              capturedPieces.black.map((piece, i) => (
                <motion.span
                  key={i}
                  className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold"
                  style={{
                    background: theme.colors.pieceRed,
                    color: '#FFD700',
                    border: '1px solid #B87333',
                  }}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ delay: i * 0.05 }}
                >
                  {pieceIcons[piece] || piece}
                </motion.span>
              ))
            )}
          </div>
        </div>
      </div>
    </Panel>
  );
}

// ============================================
// 组件: 走棋记录
// ============================================

interface MoveHistoryProps {
  theme: Theme;
  moves: string[];
}

function MoveHistory({ theme, moves }: MoveHistoryProps) {
  return (
    <Panel theme={theme} title="走棋记录">
      <div 
        className="h-48 overflow-y-auto space-y-1 pr-2"
        style={{
          scrollbarWidth: 'thin',
          scrollbarColor: `${theme.ui.panelBorder} transparent`,
        }}
      >
        {moves.length === 0 ? (
          <div 
            className="text-center py-8"
            style={{ color: theme.colors.textMuted }}
          >
            暂无走棋记录
          </div>
        ) : (
          moves.map((move, index) => (
            <motion.div
              key={index}
              className="flex items-center gap-2 p-2 rounded"
              style={{
                background: index % 2 === 0 ? 'rgba(255,255,255,0.05)' : 'transparent',
              }}
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.02 }}
            >
              <span 
                className="text-xs w-8"
                style={{ color: theme.colors.textMuted }}
              >
                {index + 1}.
              </span>
              <span style={{ color: theme.colors.text }}>
                {move}
              </span>
            </motion.div>
          ))
        )}
      </div>
    </Panel>
  );
}

// ============================================
// 主组件: GameUI
// ============================================

export function GameUI({
  themeId = 'mingqing',
  onThemeChange,
  currentPlayer = 'red',
  moveHistory = [],
  capturedPieces = { red: [], black: [] },
  timer = { red: 0, black: 0 },
  onUndo,
  onReset,
  onSettings,
}: GameUIProps) {
  const theme = themes[themeId] || defaultTheme;
  const [showSettings, setShowSettings] = useState(false);

  return (
    <div 
      className="w-full h-full flex flex-col gap-4 p-4"
      style={{ 
        background: theme.colors.background,
        fontFamily: theme.ui.fontFamily,
      }}
    >
      {/* 顶部: 玩家信息 */}
      <div className="grid grid-cols-2 gap-4">
        <PlayerInfo
          theme={theme}
          isRed={true}
          isActive={currentPlayer === 'red'}
          time={timer.red}
          capturedCount={capturedPieces.red.length}
        />
        <PlayerInfo
          theme={theme}
          isRed={false}
          isActive={currentPlayer === 'black'}
          time={timer.black}
          capturedCount={capturedPieces.black.length}
        />
      </div>

      {/* 中部: 游戏控制 */}
      <div className="flex gap-2">
        <Button theme={theme} onClick={onUndo} variant="secondary" icon="↩">
          悔棋
        </Button>
        <Button theme={theme} onClick={onReset} variant="secondary" icon="⟲">
          重新开始
        </Button>
        <Button 
          theme={theme} 
          onClick={() => setShowSettings(!showSettings)} 
          variant="primary"
          icon="⚙"
        >
          主题设置
        </Button>
      </div>

      {/* 主题选择器 */}
      <AnimatePresence>
        {showSettings && onThemeChange && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: theme.animation.uiTransition / 1000 }}
          >
            <ThemeSelectorPanel
              theme={theme}
              currentThemeId={themeId}
              onThemeChange={(id) => {
                onThemeChange(id);
                setShowSettings(false);
              }}
            />
          </motion.div>
        )}
      </AnimatePresence>

      {/* 吃子记录 */}
      <CapturedPieces theme={theme} capturedPieces={capturedPieces} />

      {/* 走棋记录 */}
      <MoveHistory theme={theme} moves={moveHistory} />
    </div>
  );
}

export default GameUI;

