/**
 * 3D Chinese Chess - Shared Types
 * High Standard Type Definitions
 */

// Player types
export type PlayerColor = 'red' | 'black';
export type PlayerRole = 'player' | 'spectator';

// Game status
export type GameStatus = 
  | 'waiting' 
  | 'playing' 
  | 'check' 
  | 'checkmate' 
  | 'stalemate' 
  | 'draw';

// Piece types
export type PieceType = 
  | 'king'      // 将/帅
  | 'advisor'   // 士/仕
  | 'elephant'  // 象/相
  | 'horse'     // 马/傌
  | 'rook'      // 车/俥
  | 'cannon'    // 炮/炮
  | 'pawn';     // 卒/兵

// Piece definition
export interface Piece {
  id: string;
  type: PieceType;
  color: PlayerColor;
  position: Position;
  hasMoved: boolean;
}

// Position on board
export interface Position {
  x: number; // 0-8 (file)
  y: number; // 0-9 (rank)
}

// Move definition
export interface Move {
  piece: Piece;
  from: Position;
  to: Position;
  capturedPiece?: Piece;
  isCheck?: boolean;
  isCheckmate?: boolean;
  timestamp: number;
}

// Game state
export interface GameState {
  id: string;
  status: GameStatus;
  currentPlayer: PlayerColor;
  board: (Piece | null)[][];
  moves: Move[];
  capturedPieces: {
    red: Piece[];
    black: Piece[];
  };
  players: {
    red?: Player;
    black?: Player;
  };
  spectators: Player[];
  startTime?: number;
  endTime?: number;
}

// Player definition
export interface Player {
  id: string;
  name: string;
  color?: PlayerColor;
  role: PlayerRole;
  rating: number;
  avatar?: string;
  isAI?: boolean;
  aiDifficulty?: AIDifficulty;
}

// AI difficulty
export type AIDifficulty = 'beginner' | 'intermediate' | 'advanced' | 'master';

// Theme types (4 Historical Styles)
export type ThemeType = 
  | 'qinhan'    // 秦汉古韵 - Ancient Bronze
  | 'tangsong'  // 唐宋风华 - Golden Glory
  | 'mingqing'  // 明清雅致 - Elegant Rosewood
  | 'modern';   // 现代简约 - Modern Minimalist

// Theme definition
export interface Theme {
  id: ThemeType;
  name: string;
  nameEn: string;
  description: string;
  colors: {
    primary: string;
    secondary: string;
    accent: string;
    background: string;
    board: string;
    pieceRed: string;
    pieceBlack: string;
    grid: string;
    highlight: string;
    selection: string;
  };
  materials: {
    board: string;
    piece: string;
    highlight: string;
  };
  lighting: {
    ambient: number;
    directional: number;
    point: number;
  };
}

// UI State
export interface UIState {
  selectedPiece: Piece | null;
  validMoves: Position[];
  lastMove: Move | null;
  hoveredSquare: Position | null;
  showCoordinates: boolean;
  currentTheme: ThemeType;
  cameraAngle: CameraAngle;
  isRotating: boolean;
}

// Camera angles
export type CameraAngle = 
  | 'top' 
  | 'side-red' 
  | 'side-black' 
  | 'isometric' 
  | 'free';

// Game settings
export interface GameSettings {
  theme: ThemeType;
  soundEnabled: boolean;
  animationSpeed: number;
  showHints: boolean;
  showCoordinates: boolean;
  cameraAngle: CameraAngle;
  autoRotate: boolean;
}

// User account
export interface User {
  id: string;
  username: string;
  email: string;
  rating: number;
  gamesPlayed: number;
  gamesWon: number;
  gamesLost: number;
  gamesDrawn: number;
  rank: PlayerRank;
  avatar?: string;
  createdAt: number;
  lastLoginAt: number;
}

// Player rank
export type PlayerRank = 
  | 'beginner'      // 初学者
  | 'novice'        // 新手
  | 'intermediate'  // 中级
  | 'advanced'      // 高级
  | 'expert'        // 专家
  | 'master'        // 大师
  | 'grandmaster';  // 特级大师

// Room types
export type GameType = 'ranked' | 'casual' | 'friendly';
export type RoomStatus = 'waiting' | 'playing' | 'finished';

export interface RoomPlayer {
  id: string;
  nickname: string;
  side: PlayerColor | null;
  isReady: boolean;
  rating: number;
}

export interface Room {
  id: string;
  name: string;
  hostId: string;
  players: RoomPlayer[];
  spectators: string[];
  status: RoomStatus;
  gameType: GameType;
  timeControl: {
    initialTime: number;
    increment: number;
  };
  createdAt: number;
  password?: string;
}

// Alias for compatibility
export type PieceColor = PlayerColor;

// Socket events
export enum SocketEvents {
  // Connection
  CONNECT = 'connect',
  DISCONNECT = 'disconnect',

  // Game
  CREATE_GAME = 'game:create',
  JOIN_GAME = 'game:join',
  LEAVE_GAME = 'game:leave',
  MAKE_MOVE = 'game:move',
  GAME_STATE = 'game:state',
  GAME_END = 'game:end',

  // Spectator
  SPECTATE_GAME = 'game:spectate',

  // Chat
  CHAT_MESSAGE = 'chat:message',

  // Error
  ERROR = 'error',
}

// API Response
export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

import { Socket } from 'socket.io';
import { 
  GameState, 
  GameStatus, 
  PieceColor, 
  PieceType, 
  Piece,
  Position,
  MoveRecord,
  RoomPlayer
} from '../types/index.js';
import { RoomManager } from '../room/RoomManager.js';

// Initial board setup
const INITIAL_BOARD: (Piece | null)[][] = [
  // Black side (row 0-4)
  [
    { type: PieceType.ROOK, color: PieceColor.BLACK, id: 'b-r-0' },
    { type: PieceType.HORSE, color: PieceColor.BLACK, id: 'b-h-0' },
    { type: PieceType.ELEPHANT, color: PieceColor.BLACK, id: 'b-e-0' },
    { type: PieceType.ADVISOR, color: PieceColor.BLACK, id: 'b-a-0' },
    { type: PieceType.KING, color: PieceColor.BLACK, id: 'b-k' },
    { type: PieceType.ADVISOR, color: PieceColor.BLACK, id: 'b-a-1' },
    { type: PieceType.ELEPHANT, color: PieceColor.BLACK, id: 'b-e-1' },
    { type: PieceType.HORSE, color: PieceColor.BLACK, id: 'b-h-1' },
    { type: PieceType.ROOK, color: PieceColor.BLACK, id: 'b-r-1' }
  ],
  [null, null, null, null, null, null, null, null, null],
  [
    null,
    { type: PieceType.CANNON, color: PieceColor.BLACK, id: 'b-c-0' },
    null, null, null, null, null,
    { type: PieceType.CANNON, color: PieceColor.BLACK, id: 'b-c-1' },
    null
  ],
  [
    { type: PieceType.PAWN, color: PieceColor.BLACK, id: 'b-p-0' }, null,
    { type: PieceType.PAWN, color: PieceColor.BLACK, id: 'b-p-1' }, null,
    { type: PieceType.PAWN, color: PieceColor.BLACK, id: 'b-p-2' }, null,
    { type: PieceType.PAWN, color: PieceColor.BLACK, id: 'b-p-3' }, null,
    { type: PieceType.PAWN, color: PieceColor.BLACK, id: 'b-p-4' }
  ],
  [null, null, null, null, null, null, null, null, null],
  // River (row 5)
  [null, null, null, null, null, null, null, null, null],
  // Red side (row 6-9)
  [
    { type: PieceType.PAWN, color: PieceColor.RED, id: 'r-p-0' }, null,
    { type: PieceType.PAWN, color: PieceColor.RED, id: 'r-p-1' }, null,
    { type: PieceType.PAWN, color: PieceColor.RED, id: 'r-p-2' }, null,
    { type: PieceType.PAWN, color: PieceColor.RED, id: 'r-p-3' }, null,
    { type: PieceType.PAWN, color: PieceColor.RED, id: 'r-p-4' }
  ],
  [
    null,
    { type: PieceType.CANNON, color: PieceColor.RED, id: 'r-c-0' },
    null, null, null, null, null,
    { type: PieceType.CANNON, color: PieceColor.RED, id: 'r-c-1' },
    null
  ],
  [null, null, null, null, null, null, null, null, null],
  [
    { type: PieceType.ROOK, color: PieceColor.RED, id: 'r-r-0' },
    { type: PieceType.HORSE, color: PieceColor.RED, id: 'r-h-0' },
    { type: PieceType.ELEPHANT, color: PieceColor.RED, id: 'r-e-0' },
    { type: PieceType.ADVISOR, color: PieceColor.RED, id: 'r-a-0' },
    { type: PieceType.KING, color: PieceColor.RED, id: 'r-k' },
    { type: PieceType.ADVISOR, color: PieceColor.RED, id: 'r-a-1' },
    { type: PieceType.ELEPHANT, color: PieceColor.RED, id: 'r-e-1' },
    { type: PieceType.HORSE, color: PieceColor.RED, id: 'r-h-1' },
    { type: PieceType.ROOK, color: PieceColor.RED, id: 'r-r-1' }
  ]
];

export class GameManager {
  private games: Map<string, GameState> = new Map(); // roomId -> gameState
  private playerGames: Map<string, string> = new Map(); // socketId -> roomId
  private roomManager: RoomManager = new RoomManager();
  private drawOffers: Map<string, string> = new Map(); // roomId -> playerId who offered

  constructor() {}

  setRoomManager(roomManager: RoomManager) {
    this.roomManager = roomManager;
  }

  playerReady(socket: Socket): void {
    const room = this.roomManager.getRoom(socket.id);
    if (!room) {
      socket.emit('game:error', { message: '您不在房间中' });
      return;
    }

    // Toggle ready status
    const player = room.players.find((p: RoomPlayer) => p.id === socket.id);
    if (player) {
      player.isReady = !player.isReady;

      // Notify all players
      socket.to(room.id).emit('room:updated', { room });
      socket.emit('room:updated', { room });

      // Check if both players are ready
      if (room.players.length === 2 && room.players.every((p: RoomPlayer) => p.isReady)) {
        this.startGame(room.id, socket);
      }
    }
  }

  startGame(roomId: string, socket: Socket): void {
    const room = this.roomManager.getRoomById(roomId);
    if (!room || room.players.length !== 2) return;

    // Assign sides
    this.roomManager.assignSides(roomId);

    // Create game state
    const redPlayer = room.players.find((p: RoomPlayer) => p.side === PieceColor.RED);
    const blackPlayer = room.players.find((p: RoomPlayer) => p.side === PieceColor.BLACK);

    if (!redPlayer || !blackPlayer) return;

    const gameState: GameState = {
      roomId,
      board: this.deepCopyBoard(INITIAL_BOARD),
      currentPlayer: PieceColor.RED,
      moveHistory: [],
      status: GameStatus.PLAYING,
      winner: null,
      redPlayer: redPlayer.id,
      blackPlayer: blackPlayer.id,
      redTimeRemaining: room.timeControl.initialTime,
      blackTimeRemaining: room.timeControl.initialTime,
      lastMoveTime: new Date()
    };

    this.games.set(roomId, gameState);
    this.playerGames.set(redPlayer.id, roomId);
    this.playerGames.set(blackPlayer.id, roomId);

    // Update room status
    this.roomManager.startGame(roomId);

    // Notify players
    socket.to(roomId).emit('game:started', { gameState });
    socket.emit('game:started', { gameState });

    console.log(`Game started in room ${roomId}`);
  }

  handleMove(socket: Socket, data: { from: Position; to: Position }): void {
    const roomId = this.playerGames.get(socket.id);
    if (!roomId) {
      socket.emit('game:error', { message: '您不在游戏中' });
      return;
    }

    const gameState = this.games.get(roomId);
    if (!gameState) {
      socket.emit('game:error', { message: '游戏不存在' });
      return;
    }

    // Check if game is still playing
    if (gameState.status !== GameStatus.PLAYING && gameState.status !== GameStatus.CHECK) {
      socket.emit('game:error', { message: '游戏已结束' });
      return;
    }

    // Check if it's player's turn
    const playerColor = gameState.redPlayer === socket.id ? PieceColor.RED : PieceColor.BLACK;
    if (gameState.currentPlayer !== playerColor) {
      socket.emit('game:error', { message: '不是您的回合' });
      return;
    }

    // Validate move (basic bounds checking)
    const { from, to } = data;
    if (!this.isValidPosition(from) || !this.isValidPosition(to)) {
      socket.emit('game:error', { message: '无效的坐标' });
      return;
    }

    // Get piece at from position
    const piece = gameState.board[from.y][from.x];
    if (!piece || piece.color !== playerColor) {
      socket.emit('game:error', { message: '无效的棋子' });
      return;
    }

    // Check if move is valid for this piece type
    if (!this.isValidMoveForPiece(gameState.board, piece, from, to)) {
      socket.emit('game:error', { message: '无效的移动' });
      return;
    }

    // Execute move
    const capturedPiece = gameState.board[to.y][to.x];
    gameState.board[to.y][to.x] = piece;
    gameState.board[from.y][from.x] = null;

    // Update time
    const now = new Date();
    const elapsed = (now.getTime() - gameState.lastMoveTime.getTime()) / 1000;
    if (playerColor === PieceColor.RED) {
      gameState.redTimeRemaining = Math.max(0, gameState.redTimeRemaining - elapsed + gameState.roomId ? 0 : 0);
    } else {
      gameState.blackTimeRemaining = Math.max(0, gameState.blackTimeRemaining - elapsed);
    }
    gameState.lastMoveTime = now;

    // Create move record
    const moveRecord: MoveRecord = {
      id: `${gameState.moveHistory.length + 1}`,
      piece,
      from,
      to,
      capturedPiece,
      timestamp: now,
      notation: this.toNotation(piece, from, to, capturedPiece),
      isCheck: false,
      isCheckmate: false
    };

    // Check for check/checkmate
    const opponentColor = playerColor === PieceColor.RED ? PieceColor.BLACK : PieceColor.RED;
    if (this.isKingInCheck(gameState.board, opponentColor)) {
      moveRecord.isCheck = true;
      gameState.status = GameStatus.CHECK;

      if (this.isCheckmate(gameState.board, opponentColor)) {
        moveRecord.isCheckmate = true;
        gameState.status = GameStatus.CHECKMATE;
        gameState.winner = playerColor;
        this.endGame(roomId, playerColor, 'checkmate');
      }
    } else {
      gameState.status = GameStatus.PLAYING;
    }

    // Check for stalemate
    if (this.isStalemate(gameState.board, opponentColor)) {
      gameState.status = GameStatus.STALEMATE;
      this.endGame(roomId, null, 'stalemate');
    }

    gameState.moveHistory.push(moveRecord);
    gameState.currentPlayer = opponentColor;

    // Notify all players
    socket.to(roomId).emit('game:move', { move: moveRecord, gameState });
    socket.emit('game:move', { move: moveRecord, gameState });

    console.log(`Move in room ${roomId}: ${moveRecord.notation}`);
  }

  playerResign(socket: Socket): void {
    const roomId = this.playerGames.get(socket.id);
    if (!roomId) {
      socket.emit('game:error', { message: '您不在游戏中' });
      return;
    }

    const gameState = this.games.get(roomId);
    if (!gameState) return;

    const playerColor = gameState.redPlayer === socket.id ? PieceColor.RED : PieceColor.BLACK;
    const winner = playerColor === PieceColor.RED ? PieceColor.BLACK : PieceColor.RED;

    this.endGame(roomId, winner, 'resigned');
  }

  offerDraw(socket: Socket): void {
    const roomId = this.playerGames.get(socket.id);
    if (!roomId) {
      socket.emit('game:error', { message: '您不在游戏中' });
      return;
    }

    const gameState = this.games.get(roomId);
    if (!gameState) return;

    // Check if already offered
    if (this.drawOffers.has(roomId)) {
      socket.emit('game:error', { message: '已有和棋请求待处理' });
      return;
    }

    this.drawOffers.set(roomId, socket.id);

    // Notify opponent
    const opponentId = gameState.redPlayer === socket.id ? gameState.blackPlayer : gameState.redPlayer;
    socket.to(opponentId).emit('game:draw:offered', { by: socket.id });
    socket.emit('game:draw:offered', { by: socket.id });
  }

  respondToDraw(socket: Socket, data: { accepted: boolean }): void {
    const roomId = this.playerGames.get(socket.id);
    if (!roomId) {
      socket.emit('game:error', { message: '您不在游戏中' });
      return;
    }

    const offererId = this.drawOffers.get(roomId);
    if (!offererId) {
      socket.emit('game:error', { message: '没有待处理的和棋请求' });
      return;
    }

    this.drawOffers.delete(roomId);

    if (data.accepted) {
      this.endGame(roomId, null, 'draw');
    } else {
      // Notify offerer that draw was declined
      socket.to(offererId).emit('game:draw:responded', { accepted: false });
      socket.emit('game:draw:responded', { accepted: false });
    }
  }

  handleDisconnect(socket: Socket): void {
    const roomId = this.playerGames.get(socket.id);
    if (roomId) {
      const gameState = this.games.get(roomId);
      if (gameState && gameState.status === GameStatus.PLAYING) {
        // Opponent wins by disconnect
        const winner = gameState.redPlayer === socket.id ? PieceColor.BLACK : PieceColor.RED;
        this.endGame(roomId, winner, 'disconnected');
      }
    }
  }

  private endGame(roomId: string, winner: PieceColor | null, reason: string): void {
    const gameState = this.games.get(roomId);
    if (!gameState) return;

    gameState.status = GameStatus.DRAW;
    gameState.winner = winner;

    // Update room
    this.roomManager.endGame(roomId);

    // Notify players - use a broadcast approach
    // This will be handled by the caller having access to io
  }

  broadcastGameEnd(roomId: string, winner: PieceColor | null, reason: string): void {
    // This method should be called from index.ts with io instance
    // Cleanup is handled in the calling code
    console.log(`Game ended in room ${roomId}: ${reason}, winner: ${winner}`);
  }

  // Validation methods (simplified versions)
  private isValidPosition(pos: Position): boolean {
    return pos.x >= 0 && pos.x <= 8 && pos.y >= 0 && pos.y <= 9;
  }

  private isValidMoveForPiece(
    board: (Piece | null)[][],
    piece: Piece,
    from: Position,
    to: Position
  ): boolean {
    // This is a simplified version - in production, use the full rule engine
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const absDx = Math.abs(dx);
    const absDy = Math.abs(dy);

    // Can't capture own piece
    const targetPiece = board[to.y][to.x];
    if (targetPiece && targetPiece.color === piece.color) {
      return false;
    }

    switch (piece.type) {
      case PieceType.KING:
        // King moves one step in palace
        if (absDx + absDy !== 1) return false;
        if (piece.color === PieceColor.RED) {
          return to.y >= 7 && to.x >= 3 && to.x <= 5;
        } else {
          return to.y <= 2 && to.x >= 3 && to.x <= 5;
        }

      case PieceType.ADVISOR:
        // Advisor moves diagonally one step in palace
        if (absDx !== 1 || absDy !== 1) return false;
        if (piece.color === PieceColor.RED) {
          return to.y >= 7 && to.x >= 3 && to.x <= 5;
        } else {
          return to.y <= 2 && to.x >= 3 && to.x <= 5;
        }

      case PieceType.ELEPHANT:
        // Elephant moves diagonally two steps, can't cross river
        if (absDx !== 2 || absDy !== 2) return false;
        if (piece.color === PieceColor.RED && to.y < 5) return false;
        if (piece.color === PieceColor.BLACK && to.y > 4) return false;
        return true;

      case PieceType.HORSE:
        // Horse moves in L shape
        return (absDx === 1 && absDy === 2) || (absDx === 2 && absDy === 1);

      case PieceType.ROOK:
        // Rook moves horizontally or vertically
        if (dx !== 0 && dy !== 0) return false;
        return this.isPathClear(board, from, to);

      case PieceType.CANNON:
        // Cannon moves like rook but captures differently
        if (dx !== 0 && dy !== 0) return false;
        if (!targetPiece) {
          return this.isPathClear(board, from, to);
        } else {
          return this.countPiecesBetween(board, from, to) === 1;
        }

      case PieceType.PAWN:
        // Pawn moves forward, after crossing river can move sideways
        const forward = piece.color === PieceColor.RED ? -1 : 1;
        if (from.y === to.y) {
          // Sideways move (only after crossing river)
          if (absDx !== 1) return false;
          if (piece.color === PieceColor.RED && from.y > 4) return false;
          if (piece.color === PieceColor.BLACK && from.y < 5) return false;
          return true;
        } else {
          // Forward move
          return dx === 0 && dy === forward;
        }

      default:
        return false;
    }
  }

  private isPathClear(board: (Piece | null)[][], from: Position, to: Position): boolean {
    const dx = Math.sign(to.x - from.x);
    const dy = Math.sign(to.y - from.y);
    let x = from.x + dx;
    let y = from.y + dy;

    while (x !== to.x || y !== to.y) {
      if (board[y][x] !== null) return false;
      x += dx;
      y += dy;
    }

    return true;
  }

  private countPiecesBetween(board: (Piece | null)[][], from: Position, to: Position): number {
    let count = 0;
    const dx = Math.sign(to.x - from.x);
    const dy = Math.sign(to.y - from.y);
    let x = from.x + dx;
    let y = from.y + dy;

    while (x !== to.x || y !== to.y) {
      if (board[y][x] !== null) count++;
      x += dx;
      y += dy;
    }

    return count;
  }

  private isKingInCheck(board: (Piece | null)[][], color: PieceColor): boolean {
    // Find king position
    let kingPos: Position | null = null;
    for (let y = 0; y < 10; y++) {
      for (let x = 0; x < 9; x++) {
        const piece = board[y][x];
        if (piece && piece.type === PieceType.KING && piece.color === color) {
          kingPos = { x, y };
          break;
        }
      }
      if (kingPos) break;
    }

    if (!kingPos) return false;

    // Check if any opponent piece can capture the king
    const opponentColor = color === PieceColor.RED ? PieceColor.BLACK : PieceColor.RED;
    for (let y = 0; y < 10; y++) {
      for (let x = 0; x < 9; x++) {
        const piece = board[y][x];
        if (piece && piece.color === opponentColor) {
          if (this.isValidMoveForPiece(board, piece, { x, y }, kingPos)) {
            return true;
          }
        }
      }
    }

    return false;
  }

  private isCheckmate(board: (Piece | null)[][], color: PieceColor): boolean {
    // Simplified checkmate detection
    // In a full implementation, this would check all possible moves
    return this.isKingInCheck(board, color) && !this.hasAnyValidMove(board, color);
  }

  private isStalemate(board: (Piece | null)[][], color: PieceColor): boolean {
    return !this.isKingInCheck(board, color) && !this.hasAnyValidMove(board, color);
  }

  private hasAnyValidMove(board: (Piece | null)[][], color: PieceColor): boolean {
    // Simplified - check if any piece can move
    for (let y = 0; y < 10; y++) {
      for (let x = 0; x < 9; x++) {
        const piece = board[y][x];
        if (piece && piece.color === color) {
          for (let ty = 0; ty < 10; ty++) {
            for (let tx = 0; tx < 9; tx++) {
              if (this.isValidMoveForPiece(board, piece, { x, y }, { x: tx, y: ty })) {
                return true;
              }
            }
          }
        }
      }
    }
    return false;
  }

  private toNotation(piece: Piece, from: Position, to: Position, _captured: Piece | null): string {
    const pieceNames: Record<PieceType, string> = {
      [PieceType.KING]: '将',
      [PieceType.ADVISOR]: '士',
      [PieceType.ELEPHANT]: '象',
      [PieceType.HORSE]: '马',
      [PieceType.ROOK]: '车',
      [PieceType.CANNON]: '炮',
      [PieceType.PAWN]: '兵'
    };

    const colNames = piece.color === PieceColor.RED 
      ? ['九', '八', '七', '六', '五', '四', '三', '二', '一']
      : ['1', '2', '3', '4', '5', '6', '7', '8', '9'];

    const action = from.x === to.x ? '平' : (to.x > from.x ? '进' : '退');
    const targetCol = colNames[to.x];

    return `${pieceNames[piece.type]}${colNames[from.x]}${action}${targetCol}`;
  }

  private deepCopyBoard(board: (Piece | null)[][]): (Piece | null)[][] {
    return board.map(row => row.map(piece => piece ? { ...piece } : null));
  }

  getGameState(roomId: string): GameState | undefined {
    return this.games.get(roomId);
  }

  getStats() {
    const games = Array.from(this.games.values());
    return {
      total: games.length,
      playing: games.filter(g => g.status === GameStatus.PLAYING).length,
      finished: games.filter(g => g.status !== GameStatus.PLAYING).length
    };
  }
}

