/**
 * 中国象棋游戏引擎 - 完整规则实现
 * 包含所有棋子移动规则、将军/将死检测等
 */

// 类型定义
export type PlayerColor = 'red' | 'black';
export type PieceType = 'king' | 'advisor' | 'elephant' | 'horse' | 'rook' | 'cannon' | 'pawn';

export interface Position {
  x: number; // 0-8 (列)
  y: number; // 0-9 (行)
}

export interface Piece {
  id: string;
  type: PieceType;
  color: PlayerColor;
  position: Position;
  hasMoved?: boolean;
}

export interface Move {
  piece: Piece;
  from: Position;
  to: Position;
  capturedPiece?: Piece;
  isCheck?: boolean;
  isCheckmate?: boolean;
  notation?: string;
}

export type Board = (Piece | null)[][];

export interface GameState {
  board: Board;
  currentPlayer: PlayerColor;
  moveHistory: Move[];
  status: 'playing' | 'check' | 'checkmate' | 'stalemate' | 'draw';
  winner?: PlayerColor;
  capturedPieces: { red: Piece[]; black: Piece[] };
}

// 棋子中文名称
const PIECE_NAMES: Record<PieceType, { red: string; black: string }> = {
  king: { red: '帅', black: '将' },
  advisor: { red: '仕', black: '士' },
  elephant: { red: '相', black: '象' },
  horse: { red: '马', black: '马' },
  rook: { red: '车', black: '车' },
  cannon: { red: '炮', black: '炮' },
  pawn: { red: '兵', black: '卒' },
};

// 列名（红方从右到左，黑方从左到右）
const RED_COLS = ['九', '八', '七', '六', '五', '四', '三', '二', '一'];
const BLACK_COLS = ['1', '2', '3', '4', '5', '6', '7', '8', '9'];

// 初始化棋盘
export function createInitialBoard(): Board {
  const board: Board = Array(10).fill(null).map(() => Array(9).fill(null));

  // 黑方（上方，y=0-4）
  board[0][0] = { id: 'b-r-0', type: 'rook', color: 'black', position: { x: 0, y: 0 } };
  board[0][1] = { id: 'b-h-0', type: 'horse', color: 'black', position: { x: 1, y: 0 } };
  board[0][2] = { id: 'b-e-0', type: 'elephant', color: 'black', position: { x: 2, y: 0 } };
  board[0][3] = { id: 'b-a-0', type: 'advisor', color: 'black', position: { x: 3, y: 0 } };
  board[0][4] = { id: 'b-k', type: 'king', color: 'black', position: { x: 4, y: 0 } };
  board[0][5] = { id: 'b-a-1', type: 'advisor', color: 'black', position: { x: 5, y: 0 } };
  board[0][6] = { id: 'b-e-1', type: 'elephant', color: 'black', position: { x: 6, y: 0 } };
  board[0][7] = { id: 'b-h-1', type: 'horse', color: 'black', position: { x: 7, y: 0 } };
  board[0][8] = { id: 'b-r-1', type: 'rook', color: 'black', position: { x: 8, y: 0 } };

  board[2][1] = { id: 'b-c-0', type: 'cannon', color: 'black', position: { x: 1, y: 2 } };
  board[2][7] = { id: 'b-c-1', type: 'cannon', color: 'black', position: { x: 7, y: 2 } };

  board[3][0] = { id: 'b-p-0', type: 'pawn', color: 'black', position: { x: 0, y: 3 } };
  board[3][2] = { id: 'b-p-1', type: 'pawn', color: 'black', position: { x: 2, y: 3 } };
  board[3][4] = { id: 'b-p-2', type: 'pawn', color: 'black', position: { x: 4, y: 3 } };
  board[3][6] = { id: 'b-p-3', type: 'pawn', color: 'black', position: { x: 6, y: 3 } };
  board[3][8] = { id: 'b-p-4', type: 'pawn', color: 'black', position: { x: 8, y: 3 } };

  // 红方（下方，y=6-9）
  board[9][0] = { id: 'r-r-0', type: 'rook', color: 'red', position: { x: 0, y: 9 } };
  board[9][1] = { id: 'r-h-0', type: 'horse', color: 'red', position: { x: 1, y: 9 } };
  board[9][2] = { id: 'r-e-0', type: 'elephant', color: 'red', position: { x: 2, y: 9 } };
  board[9][3] = { id: 'r-a-0', type: 'advisor', color: 'red', position: { x: 3, y: 9 } };
  board[9][4] = { id: 'r-k', type: 'king', color: 'red', position: { x: 4, y: 9 } };
  board[9][5] = { id: 'r-a-1', type: 'advisor', color: 'red', position: { x: 5, y: 9 } };
  board[9][6] = { id: 'r-e-1', type: 'elephant', color: 'red', position: { x: 6, y: 9 } };
  board[9][7] = { id: 'r-h-1', type: 'horse', color: 'red', position: { x: 7, y: 9 } };
  board[9][8] = { id: 'r-r-1', type: 'rook', color: 'red', position: { x: 8, y: 9 } };

  board[7][1] = { id: 'r-c-0', type: 'cannon', color: 'red', position: { x: 1, y: 7 } };
  board[7][7] = { id: 'r-c-1', type: 'cannon', color: 'red', position: { x: 7, y: 7 } };

  board[6][0] = { id: 'r-p-0', type: 'pawn', color: 'red', position: { x: 0, y: 6 } };
  board[6][2] = { id: 'r-p-1', type: 'pawn', color: 'red', position: { x: 2, y: 6 } };
  board[6][4] = { id: 'r-p-2', type: 'pawn', color: 'red', position: { x: 4, y: 6 } };
  board[6][6] = { id: 'r-p-3', type: 'pawn', color: 'red', position: { x: 6, y: 6 } };
  board[6][8] = { id: 'r-p-4', type: 'pawn', color: 'red', position: { x: 8, y: 6 } };

  return board;
}

// 创建初始游戏状态
export function createInitialGameState(): GameState {
  return {
    board: createInitialBoard(),
    currentPlayer: 'red',
    moveHistory: [],
    status: 'playing',
    capturedPieces: { red: [], black: [] },
  };
}

// 检查位置是否在棋盘内
export function isValidPosition(pos: Position): boolean {
  return pos.x >= 0 && pos.x <= 8 && pos.y >= 0 && pos.y <= 9;
}

// 检查位置是否在九宫格内
export function isInPalace(pos: Position, color: PlayerColor): boolean {
  if (pos.x < 3 || pos.x > 5) return false;
  if (color === 'red') {
    return pos.y >= 7 && pos.y <= 9;
  } else {
    return pos.y >= 0 && pos.y <= 2;
  }
}

// 检查路径是否清晰（用于车、炮）
export function isPathClear(board: Board, from: Position, to: Position): boolean {
  const dx = Math.sign(to.x - from.x);
  const dy = Math.sign(to.y - from.y);
  let x = from.x + dx;
  let y = from.y + dy;

  while (x !== to.x || y !== to.y) {
    if (board[y][x] !== null) return false;
    x += dx;
    y += dy;
  }

  return true;
}

// 计算两点之间的棋子数量（用于炮）
export function countPiecesBetween(board: Board, from: Position, to: Position): number {
  let count = 0;
  const dx = Math.sign(to.x - from.x);
  const dy = Math.sign(to.y - from.y);
  let x = from.x + dx;
  let y = from.y + dy;

  while (x !== to.x || y !== to.y) {
    if (board[y][x] !== null) count++;
    x += dx;
    y += dy;
  }

  return count;
}

// 检查棋子移动是否有效
export function isValidMove(
  board: Board,
  piece: Piece,
  from: Position,
  to: Position
): boolean {
  if (!isValidPosition(to)) return false;

  // 不能吃自己的棋子
  const targetPiece = board[to.y][to.x];
  if (targetPiece && targetPiece.color === piece.color) {
    return false;
  }

  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const absDx = Math.abs(dx);
  const absDy = Math.abs(dy);

  switch (piece.type) {
    case 'king':
      // 将/帅：九宫格内走一步
      if (absDx + absDy !== 1) return false;
      return isInPalace(to, piece.color);

    case 'advisor':
      // 士：九宫格内斜走一步
      if (absDx !== 1 || absDy !== 1) return false;
      return isInPalace(to, piece.color);

    case 'elephant':
      // 象：走田字，不能过河
      if (absDx !== 2 || absDy !== 2) return false;
      // 检查象眼
      const eyeX = from.x + dx / 2;
      const eyeY = from.y + dy / 2;
      if (board[eyeY][eyeX] !== null) return false;
      // 不能过河
      if (piece.color === 'red' && to.y < 5) return false;
      if (piece.color === 'black' && to.y > 4) return false;
      return true;

    case 'horse':
      // 马：走日字，检查蹩马腿
      if (!((absDx === 1 && absDy === 2) || (absDx === 2 && absDy === 1))) return false;
      // 检查马腿
      if (absDx === 2) {
        const legX = from.x + dx / 2;
        if (board[from.y][legX] !== null) return false;
      } else {
        const legY = from.y + dy / 2;
        if (board[legY][from.x] !== null) return false;
      }
      return true;

    case 'rook':
      // 车：直线走
      if (dx !== 0 && dy !== 0) return false;
      return isPathClear(board, from, to);

    case 'cannon':
      // 炮：直线走，吃子需要隔一个
      if (dx !== 0 && dy !== 0) return false;
      if (!targetPiece) {
        // 移动
        return isPathClear(board, from, to);
      } else {
        // 吃子
        return countPiecesBetween(board, from, to) === 1;
      }

    case 'pawn':
      // 兵/卒：过河前只能前进，过河后可以横走
      const forward = piece.color === 'red' ? -1 : 1;
      if (from.y === to.y) {
        // 横走（过河后）
        if (absDx !== 1) return false;
        if (piece.color === 'red' && from.y > 4) return false;
        if (piece.color === 'black' && from.y < 5) return false;
        return true;
      } else {
        // 前进
        return dx === 0 && dy === forward;
      }

    default:
      return false;
  }
}

// 找到将/帅的位置
export function findKing(board: Board, color: PlayerColor): Position | null {
  for (let y = 0; y < 10; y++) {
    for (let x = 0; x < 9; x++) {
      const piece = board[y][x];
      if (piece && piece.type === 'king' && piece.color === color) {
        return { x, y };
      }
    }
  }
  return null;
}

// 检查是否被将军
export function isKingInCheck(board: Board, color: PlayerColor): boolean {
  const kingPos = findKing(board, color);
  if (!kingPos) return false;

  const opponentColor = color === 'red' ? 'black' : 'red';

  for (let y = 0; y < 10; y++) {
    for (let x = 0; x < 9; x++) {
      const piece = board[y][x];
      if (piece && piece.color === opponentColor) {
        if (isValidMove(board, piece, { x, y }, kingPos)) {
          return true;
        }
      }
    }
  }

  return false;
}

// 检查是否有有效的移动
export function hasAnyValidMove(board: Board, color: PlayerColor): boolean {
  for (let y = 0; y < 10; y++) {
    for (let x = 0; x < 9; x++) {
      const piece = board[y][x];
      if (piece && piece.color === color) {
        for (let ty = 0; ty < 10; ty++) {
          for (let tx = 0; tx < 9; tx++) {
            const to = { x: tx, y: ty };
            if (isValidMove(board, piece, { x, y }, to)) {
              // 模拟移动
              const captured = board[ty][tx];
              board[ty][tx] = piece;
              board[y][x] = null;

              const inCheck = isKingInCheck(board, color);

              // 恢复
              board[y][x] = piece;
              board[ty][tx] = captured;

              if (!inCheck) return true;
            }
          }
        }
      }
    }
  }
  return false;
}

// 检查将死
export function isCheckmate(board: Board, color: PlayerColor): boolean {
  return isKingInCheck(board, color) && !hasAnyValidMove(board, color);
}

// 检查困毙
export function isStalemate(board: Board, color: PlayerColor): boolean {
  return !isKingInCheck(board, color) && !hasAnyValidMove(board, color);
}

// 执行移动
export function makeMove(
  gameState: GameState,
  from: Position,
  to: Position
): { success: boolean; gameState?: GameState; error?: string } {
  const { board, currentPlayer } = gameState;
  const piece = board[from.y][from.x];

  if (!piece) {
    return { success: false, error: '该位置没有棋子' };
  }

  if (piece.color !== currentPlayer) {
    return { success: false, error: '不是你的回合' };
  }

  if (!isValidMove(board, piece, from, to)) {
    return { success: false, error: '无效的移动' };
  }

  // 模拟移动检查是否会导致自己被将军
  const captured = board[to.y][to.x];
  board[to.y][to.x] = piece;
  board[from.y][from.x] = null;

  if (isKingInCheck(board, currentPlayer)) {
    // 恢复
    board[from.y][from.x] = piece;
    board[to.y][to.x] = captured;
    return { success: false, error: '移动后会被将军' };
  }

  // 创建新的游戏状态
  const newBoard = board.map(row => row.map(p => p ? { ...p } : null));
  const capturedPieces = {
    red: [...gameState.capturedPieces.red],
    black: [...gameState.capturedPieces.black],
  };

  // 更新棋子位置
  newBoard[to.y][to.x] = { ...piece, position: to, hasMoved: true };
  newBoard[from.y][from.x] = null;

  // 记录吃子
  if (captured) {
    capturedPieces[captured.color].push(captured);
  }

  // 检查游戏状态
  const nextPlayer = currentPlayer === 'red' ? 'black' : 'red';
  let status: GameState['status'] = 'playing';
  let winner: PlayerColor | undefined;

  if (isCheckmate(newBoard, nextPlayer)) {
    status = 'checkmate';
    winner = currentPlayer;
  } else if (isStalemate(newBoard, nextPlayer)) {
    status = 'stalemate';
  } else if (isKingInCheck(newBoard, nextPlayer)) {
    status = 'check';
  }

  // 创建走棋记录
  const move: Move = {
    piece: { ...piece },
    from,
    to,
    capturedPiece: captured || undefined,
    isCheck: status === 'check' || status === 'checkmate',
    isCheckmate: status === 'checkmate',
    notation: generateNotation(piece, from, to, captured),
  };

  return {
    success: true,
    gameState: {
      ...gameState,
      board: newBoard,
      currentPlayer: nextPlayer,
      status,
      winner,
      moveHistory: [...gameState.moveHistory, move],
      capturedPieces,
    },
  };
}

// 生成走棋记录（中文记谱）
export function generateNotation(
  piece: Piece,
  from: Position,
  to: Position,
  captured: Piece | null
): string {
  const name = PIECE_NAMES[piece.type][piece.color];
  const cols = piece.color === 'red' ? RED_COLS : BLACK_COLS;
  const fromCol = cols[from.x];

  let action: string;
  let target: string;

  if (from.x === to.x) {
    action = '平';
    target = cols[to.x];
  } else if ((piece.color === 'red' && to.y < from.y) || (piece.color === 'black' && to.y > from.y)) {
    action = '进';
    target = piece.type === 'horse' || piece.type === 'elephant' || piece.type === 'advisor'
      ? cols[to.x]
      : String(from.y - to.y);
  } else {
    action = '退';
    target = piece.type === 'horse' || piece.type === 'elephant' || piece.type === 'advisor'
      ? cols[to.x]
      : String(to.y - from.y);
  }

  return `${name}${fromCol}${action}${target}`;
}

// 获取棋子的所有有效移动
export function getValidMoves(board: Board, piece: Piece): Position[] {
  const moves: Position[] = [];
  const pos = piece.position;

  for (let y = 0; y < 10; y++) {
    for (let x = 0; x < 9; x++) {
      const to = { x, y };
      if (isValidMove(board, piece, pos, to)) {
        // 模拟移动检查是否会导致自己被将军
        const captured = board[y][x];
        board[y][x] = piece;
        board[pos.y][pos.x] = null;

        const inCheck = isKingInCheck(board, piece.color);

        // 恢复
        board[pos.y][pos.x] = piece;
        board[y][x] = captured;

        if (!inCheck) {
          moves.push(to);
        }
      }
    }
  }

  return moves;
}

// 深拷贝棋盘
export function deepCopyBoard(board: Board): Board {
  return board.map(row => row.map(piece => piece ? { ...piece } : null));
}

